; pi_spigot.asm - generated by gen_pi_spigot.py, do not edit by hand
; Placard CPU benchmark: Rabinowitz & Wagon spigot, 1000 digits of pi,
; printed to the screen.  See gen_pi_spigot.py for the method and memory map.
;
;     python3 placard_sim.py pi_spigot.asm --run --max-steps 2000000000 --png pi.png
;
; Date: 10/16/2026

#include "placard.asm"

#addr 0x0000
reset:
    ld   main >> 8, y
    jmp  main

#addr 0x0100
main:
    ; clear video RAM 6000-FFFF (mode bytes 0 = 1 bpp, pixels off)
    ld   0x60, ac
    ld   ac, [0x28]
clr_pg:
    ld   [0x28], y
    clr  x
clr_b:
    ld   0x00, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    bne  clr_b
    ld   [0x28], ac
    inc
    ld   ac, [0x28]
    bne  clr_pg
    ; a[i] = 2: low limb pages = 2, high limb pages = 0
    ld   0x08, ac
    ld   ac, [0x28]
fill_pg:
    ld   [0x28], y
    clr  x
fill_b:
    ld   0x02, [y,x]
    ld   [0x28], ac
    add  0x0E, y
    ld   0x00, [y,x]
    ld   [0x28], y
    ld   x, ac
    inc
    ld   ac, x
    bne  fill_b
    ld   [0x28], ac
    inc
    ld   ac, [0x28]
    sub  0x16, ac
    bne  fill_pg
    ; output state
    ld   0x00, ac
    ld   ac, [0x1C]
    ld   0x00, ac
    ld   ac, [0x1D]
    ld   0x01, ac
    ld   ac, [0x1E]
    ld   0x01, ac
    ld   ac, [0x21]
    ld   0x62, ac
    ld   ac, [0x22]
    ld   0x20, ac
    ld   ac, [0x23]
    ld   0x00, ac
    ld   ac, [0x25]
    ld   0x4F, ac
    ld   ac, [0x24]
    ld   0x68, ac
    ld   ac, [0x2B]
    ld   0x07, ac
    ld   ac, [0x2C]
    ; ---- one digit per pass ----
outer:
    ld   0x00, ac
    ld   ac, [0x15]
    ld   0x06, ac
    ld   ac, [0x18]
    ld   0x1A, ac
    ld   ac, [0x19]
    ld   0x06, ac
    ld   ac, [0x1A]
    ld   0x15, ac
    ld   ac, [0x1B]
    ld   0x0B, ac
    ld   ac, [0x2D]
    ld   0x34, ac
    ld   ac, [0x2E]
    ld   0x00, ac
    ld   ac, [0x2F]
    ld   0x16, ac
    ld   ac, [0x30]
    ld   0x68, ac
    ld   ac, [0x31]
    ld   0x00, ac
    ld   ac, [0x32]
    ld   0x2C, ac
    ld   ac, [0x33]
    ld   0x50, ac
    ld   ac, [0x34]
    ld   0x01, ac
    ld   ac, [0x35]
    ld   0x58, ac
    ld   ac, [0x36]
    ld   0x20, ac
    ld   ac, [0x37]
    ld   0x03, ac
    ld   ac, [0x38]
    ld   0x30, ac
    ld   ac, [0x39]
    ld   0x41, ac
    ld   ac, [0x3A]
    ld   0x06, ac
    ld   ac, [0x3B]
    ld   inner >> 8, y
    jmp  inner

#addr 0x0200
inner:
    ; a[i] -> al, ah
    ld   [0x1A], x
    ld   [0x1B], y
    ld   [y,x], ac
    ld   ac, [0x16]
    ld   [0x1B], ac
    add  0x0E, y
    ld   [y,x], ac
    ld   ac, [0x17]
    ; 10 * a[i]: x0 = T[10][al].lo, x1 = T[10][al].hi, x2 = T[10][ah].hi, t0 = T[10][ah].lo
    ld   [0x16], x
    ld   0x2E, y
    ld   [y,x], ac
    ld   ac, [0x10]
    ld   0x43, y
    ld   [y,x], ac
    ld   ac, [0x11]
    ld   [0x17], x
    ld   [y,x], ac
    ld   ac, [0x12]
    ld   0x2E, y
    ld   [y,x], ac
    ld   ac, [0x13]
    ; + q * i, low limbs of the table
    ld   [0x15], ac
    add  0x24, y
    ld   [0x18], x
    ld   [y,x], ac
    add  [0x10], ac
    bge  qi0
    and  0x7F, ac
    ld   ac, [0x10]
    ld   [0x11], ac
    inc
    ld   ac, [0x11]
    bra  qi1
qi0:
    ld   ac, [0x10]
qi1:
    ld   [0x19], x
    ld   [y,x], ac
    add  [0x13], ac
    bge  qi2
    and  0x7F, ac
    ld   ac, [0x13]
    ld   [0x12], ac
    inc
    ld   ac, [0x12]
    bra  qi3
qi2:
    ld   ac, [0x13]
qi3:
    ; high limbs of the table
    ld   [0x15], ac
    add  0x39, y
    ld   [0x18], x
    ld   [y,x], ac
    add  [0x11], ac
    add  [0x13], ac
    bge  qi4
    and  0x7F, ac
    ld   ac, [0x11]
    ld   [0x12], ac
    inc
    ld   ac, [0x12]
    bra  qi5
qi4:
    ld   ac, [0x11]
qi5:
    ld   [0x19], x
    ld   [y,x], ac
    add  [0x12], ac
    ld   ac, [0x12]
    ; x div (2i - 1)
    ld   0x00, ac
    ld   ac, [0x15]
    ; k = 4
    ld   [0x10], ac
    sub  [0x39], ac
    bge  n0_1
    and  0x7F, ac
    ld   ac, [0x13]
    ld   [0x11], ac
    dec
    bra  m0_2
n0_1:
    ld   ac, [0x13]
    ld   [0x11], ac
m0_2:
    sub  [0x3A], ac
    bge  n1_3
    and  0x7F, ac
    ld   ac, [0x14]
    ld   [0x12], ac
    dec
    bra  m1_4
n1_3:
    ld   ac, [0x14]
    ld   [0x12], ac
m1_4:
    sub  [0x3B], ac
    blt  ns_5
    ld   ac, [0x12]
    ld   [0x14], ac
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x10, ac
    ld   ac, [0x15]
ns_5:
    ld   div2 >> 8, y
    jmp  div2

#addr 0x0300
div2:
    ; k = 3
    ld   [0x10], ac
    sub  [0x36], ac
    bge  n0_6
    and  0x7F, ac
    ld   ac, [0x13]
    ld   [0x11], ac
    dec
    bra  m0_7
n0_6:
    ld   ac, [0x13]
    ld   [0x11], ac
m0_7:
    sub  [0x37], ac
    bge  n1_8
    and  0x7F, ac
    ld   ac, [0x14]
    ld   [0x12], ac
    dec
    bra  m1_9
n1_8:
    ld   ac, [0x14]
    ld   [0x12], ac
m1_9:
    sub  [0x38], ac
    blt  ns_10
    ld   ac, [0x12]
    ld   [0x14], ac
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x08, ac
    ld   ac, [0x15]
ns_10:
    ; k = 2
    ld   [0x10], ac
    sub  [0x33], ac
    bge  n0_11
    and  0x7F, ac
    ld   ac, [0x13]
    ld   [0x11], ac
    dec
    bra  m0_12
n0_11:
    ld   ac, [0x13]
    ld   [0x11], ac
m0_12:
    sub  [0x34], ac
    bge  n1_13
    and  0x7F, ac
    ld   ac, [0x14]
    ld   [0x12], ac
    dec
    bra  m1_14
n1_13:
    ld   ac, [0x14]
    ld   [0x12], ac
m1_14:
    sub  [0x35], ac
    blt  ns_15
    ld   ac, [0x12]
    ld   [0x14], ac
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x04, ac
    ld   ac, [0x15]
ns_15:
    ; k = 1
    ld   [0x10], ac
    sub  [0x30], ac
    bge  n0_16
    and  0x7F, ac
    ld   ac, [0x13]
    ld   [0x11], ac
    dec
    bra  m0_17
n0_16:
    ld   ac, [0x13]
    ld   [0x11], ac
m0_17:
    sub  [0x31], ac
    bge  n1_18
    and  0x7F, ac
    ld   ac, [0x14]
    ld   [0x12], ac
    dec
    bra  m1_19
n1_18:
    ld   ac, [0x14]
    ld   [0x12], ac
m1_19:
    sub  [0x32], ac
    blt  ns_20
    ld   ac, [0x12]
    ld   [0x14], ac
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x02, ac
    ld   ac, [0x15]
ns_20:
    ; k = 0
    ld   [0x10], ac
    sub  [0x2D], ac
    bge  n0_21
    and  0x7F, ac
    ld   ac, [0x13]
    ld   [0x11], ac
    dec
    bra  m0_22
n0_21:
    ld   ac, [0x13]
    ld   [0x11], ac
m0_22:
    sub  [0x2E], ac
    bge  n1_23
    and  0x7F, ac
    ld   ac, [0x14]
    ld   [0x12], ac
    dec
    bra  m1_24
n1_23:
    ld   ac, [0x14]
    ld   [0x12], ac
m1_24:
    sub  [0x2F], ac
    blt  ns_25
    ld   ac, [0x12]
    ld   [0x14], ac
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x01, ac
    ld   ac, [0x15]
ns_25:
    ld   div3 >> 8, y
    jmp  div3

#addr 0x0400
div3:
    ; a[i] = remainder (x2 = 0)
    ld   [0x1A], x
    ld   [0x1B], y
    ld   [0x10], ac
    ld   ac, [y,x]
    ld   [0x1B], ac
    add  0x0E, y
    ld   [0x11], ac
    ld   ac, [y,x]
    ; step the pointer, i and the five divisors down
    ld   [0x1A], ac
    bne  pnz
    ld   [0x1B], ac
    dec
    ld   ac, [0x1B]
    ld   [0x1A], ac
pnz:
    dec
    ld   ac, [0x1A]
    ld   [0x18], ac
    dec
    bge  inz
    and  0x7F, ac
    ld   ac, [0x18]
    ld   [0x19], ac
    dec
    ld   ac, [0x19]
    bra  idone
inz:
    ld   ac, [0x18]
idone:
    ld   [0x2D], ac
    sub  0x02, ac
    bge  dok_26
    and  0x7F, ac
    ld   ac, [0x2D]
    ld   [0x2E], ac
    dec
    bge  dd_27
    and  0x7F, ac
    ld   ac, [0x2E]
    ld   [0x2F], ac
    dec
    ld   ac, [0x2F]
    bra  dx_28
dok_26:
    ld   ac, [0x2D]
    bra  dx_28
dd_27:
    ld   ac, [0x2E]
dx_28:
    ld   [0x30], ac
    sub  0x04, ac
    bge  dok_29
    and  0x7F, ac
    ld   ac, [0x30]
    ld   [0x31], ac
    dec
    bge  dd_30
    and  0x7F, ac
    ld   ac, [0x31]
    ld   [0x32], ac
    dec
    ld   ac, [0x32]
    bra  dx_31
dok_29:
    ld   ac, [0x30]
    bra  dx_31
dd_30:
    ld   ac, [0x31]
dx_31:
    ld   [0x33], ac
    sub  0x08, ac
    bge  dok_32
    and  0x7F, ac
    ld   ac, [0x33]
    ld   [0x34], ac
    dec
    bge  dd_33
    and  0x7F, ac
    ld   ac, [0x34]
    ld   [0x35], ac
    dec
    ld   ac, [0x35]
    bra  dx_34
dok_32:
    ld   ac, [0x33]
    bra  dx_34
dd_33:
    ld   ac, [0x34]
dx_34:
    ld   [0x36], ac
    sub  0x10, ac
    bge  dok_35
    and  0x7F, ac
    ld   ac, [0x36]
    ld   [0x37], ac
    dec
    bge  dd_36
    and  0x7F, ac
    ld   ac, [0x37]
    ld   [0x38], ac
    dec
    ld   ac, [0x38]
    bra  dx_37
dok_35:
    ld   ac, [0x36]
    bra  dx_37
dd_36:
    ld   ac, [0x37]
dx_37:
    ld   [0x39], ac
    sub  0x20, ac
    bge  dok_38
    and  0x7F, ac
    ld   ac, [0x39]
    ld   [0x3A], ac
    dec
    bge  dd_39
    and  0x7F, ac
    ld   ac, [0x3A]
    ld   [0x3B], ac
    dec
    ld   ac, [0x3B]
    bra  dx_40
dok_38:
    ld   ac, [0x39]
    bra  dx_40
dd_39:
    ld   ac, [0x3A]
dx_40:
    ; loop while i > 1
    ld   [0x19], ac
    bne  again
    ld   [0x18], ac
    sub  1, ac
    beq  last
again:
    ld   inner >> 8, y
    jmp  inner
last:
    ld   last_i >> 8, y
    jmp  last_i

#addr 0x0500
last_i:
    ; x = 10 * a[1] + q, a[1] = x mod 10, q = x div 10 (x <= 110)
    ld   0x08, y
    ld   0x01, x
    ld   [y,x], ac
    shl
    ld   ac, [0x13]
    shl
    shl
    add  [0x13], ac
    add  [0x15], ac
    ld   ac, [0x10]
    clr  ac
    ld   ac, [0x15]
d10:
    ld   [0x10], ac
    sub  10, ac
    blt  d10done
    ld   ac, [0x10]
    ld   [0x15], ac
    inc
    ld   ac, [0x15]
    bra  d10
d10done:
    ld   [0x10], ac
    ld   ac, [y,x]
    ; predigit handling
    ld   [0x15], ac
    sub  9, ac
    bne  not9
    ld   [0x1D], ac
    inc
    ld   ac, [0x1D]
    bra  next
not9:
    sub  1, ac
    bne  normal
    ; q = 10: held digit + 1, then the held 9s become 0s
    ld   [0x1C], ac
    inc
    ld   ac, [0x20]
    ld   ret_41, ac
    ld   ac, [0x29]
    ld   ret_41 >> 8, ac
    ld   ac, [0x2A]
    ld   emit >> 8, y
    jmp  emit
ret_41:
    ld   0x00, ac
    ld   ac, [0x1F]
    ld   0x00, ac
    ld   ac, [0x1C]
    bra  flush
normal:
    ld   [0x1E], ac
    bne  nofirst
    ld   [0x1C], ac
    ld   ac, [0x20]
    ld   ret_42, ac
    ld   ac, [0x29]
    ld   ret_42 >> 8, ac
    ld   ac, [0x2A]
    ld   emit >> 8, y
    jmp  emit
ret_42:
nofirst:
    ld   0x00, ac
    ld   ac, [0x1E]
    ld   [0x15], ac
    ld   ac, [0x1C]
    ld   0x09, ac
    ld   ac, [0x1F]
flush:
    ld   [0x1D], ac
    beq  next
    dec
    ld   ac, [0x1D]
    ld   [0x1F], ac
    ld   ac, [0x20]
    ld   ret_43, ac
    ld   ac, [0x29]
    ld   ret_43 >> 8, ac
    ld   ac, [0x2A]
    ld   emit >> 8, y
    jmp  emit
ret_43:
    bra  flush
next:
    ; digits left (base 128 counter)
    ld   [0x2B], ac
    dec
    bge  jok
    and  0x7F, ac
    ld   ac, [0x2B]
    ld   [0x2C], ac
    dec
    ld   ac, [0x2C]
    bra  jtest
jok:
    ld   ac, [0x2B]
jtest:
    ld   [0x2B], ac
    or   [0x2C], ac
    beq  finish
    ld   outer >> 8, y
    jmp  outer
finish:
    ld   [0x1C], ac
    ld   ac, [0x20]
    ld   ret_44, ac
    ld   ac, [0x29]
    ld   ret_44 >> 8, ac
    ld   ac, [0x2A]
    ld   emit >> 8, y
    jmp  emit
ret_44:
done:
    bra  done

#addr 0x0600
emit:
    ; draw glyph [dig] at the cursor, then a "." after the first digit
    ld   [0x20], ac
    shl
    shl
    shl
    ld   ac, [0x26]
    ld   [0x23], ac
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x07, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x07, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x07, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x07, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x07, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x07, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x07, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x07, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ; next character cell
    ld   [0x22], ac
    add  2, ac
    ld   ac, [0x22]
    ld   [0x24], ac
    dec
    ld   ac, [0x24]
    bne  advd
    ld   0x4F, ac
    ld   ac, [0x24]
    ld   [0x23], ac
    add  8, ac
    ld   ac, [0x23]
    bne  nlw
    ld   0x01, ac
    ld   ac, [0x25]
nlw:
    ld   0x62, ac
    add  [0x25], ac
    ld   ac, [0x22]
advd:
    ld   [0x21], ac
    beq  eret
    ld   0x00, ac
    ld   ac, [0x21]
    ld   0x0A, ac
    ld   ac, [0x20]
    bra  emit
eret:
    ld   [0x2A], y
    jmp  [0x29]

#addr 0x0700
font:      ; 0-9 and ".", 8 bytes each, leftmost pixel in bit 0
    #d8 0x0E, 0x11, 0x19, 0x15, 0x13, 0x11, 0x0E, 0x00
    #d8 0x04, 0x06, 0x04, 0x04, 0x04, 0x04, 0x0E, 0x00
    #d8 0x0E, 0x11, 0x10, 0x08, 0x04, 0x02, 0x1F, 0x00
    #d8 0x1F, 0x08, 0x04, 0x08, 0x10, 0x11, 0x0E, 0x00
    #d8 0x08, 0x0C, 0x0A, 0x09, 0x1F, 0x08, 0x08, 0x00
    #d8 0x1F, 0x01, 0x0F, 0x10, 0x10, 0x11, 0x0E, 0x00
